<?php $pageTitle='Employees';$subtitle='Create employee accounts, manage access and monitor field staff.';$active='Employees';require __DIR__.'/_layout.php';$pdo=db();$emps=$pdo->query("SELECT id,name,phone,email,status,created_at FROM users WHERE role='employee' ORDER BY id DESC")->fetchAll();$csrf=csrfToken();?><div class="grid two"><section class="card"><div class="section-head"><h2>Create employee account</h2></div><form id="employeeForm"><div class="form-grid"><div class="field"><label>Name</label><input class="input" name="name" required></div><div class="field"><label>Phone</label><input class="input" name="phone"></div><div class="field full"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field full"><label>Temporary password</label><input class="input" name="password" minlength="8" required></div></div><button class="btn primary" style="margin-top:15px">Create Employee</button></form></section><section class="card"><h2>Employee access</h2><p style="color:var(--muted);line-height:1.7">Employees sign in through the dedicated employee login. Their workspace exposes only assigned work, deliveries, attendance and profile actions.</p><a class="btn blue" href="../employee-login.php">Open Employee Login</a></section></div><div class="card" style="margin-top:18px"><div class="section-head"><h2>Employee directory</h2><span style="color:var(--muted)"><?=count($emps)?> accounts</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($emps as $e):?><tr><td><strong><?=ae($e['name'])?></strong></td><td><?=ae($e['phone'])?></td><td><?=ae($e['email'])?></td><td><span class="pill <?=($e['status']==='active'?'green':'red')?>"><?=ae($e['status'])?></span></td><td><?=ae($e['created_at'])?></td><td><button class="btn" onclick='editEmployee(<?=json_encode($e,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'>Edit</button></td></tr><?php endforeach;if(!$emps):?><tr><td colspan="6" class="empty">No employees yet.</td></tr><?php endif;?></tbody></table></div></div><div class="modal" id="empModal"><div class="modal-box" style="max-width:600px"><div class="modal-head"><h2>Edit Employee</h2><button class="close" onclick="empModal.classList.remove('open')">×</button></div><form id="editEmployee"><input type="hidden" name="id"><div class="form-grid"><div class="field"><label>Name</label><input class="input" name="name" required></div><div class="field"><label>Phone</label><input class="input" name="phone"></div><div class="field full"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field"><label>Status</label><select class="select" name="status"><option>active</option><option>inactive</option><option>blocked</option></select></div><div class="field"><label>New password (optional)</label><input class="input" name="password" minlength="8"></div></div><button class="btn primary" style="margin-top:15px">Save Employee</button></form></div></div><script>const empModal=document.querySelector('#empModal');function editEmployee(e){const f=document.querySelector('#editEmployee');for(const k of ['id','name','phone','email','status'])f.elements[k].value=e[k]??'';f.elements.password.value='';empModal.classList.add('open')}document.querySelector('#employeeForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','create-employee');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),600)});document.querySelector('#editEmployee').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('action','update-employee');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF}});const j=await r.json();toast(j.message,j.ok);if(j.ok)setTimeout(()=>location.reload(),600)});</script><?php require __DIR__.'/_foot.php'; ?>
